/// <summary>
/// designed by AVANADE
/// </summary>
[ExtensionOf(classStr(MCRFullTextSearchRefresh))]
final class AVAMCRFullTextSearchRefresh_Extension
{
    public Set existedSearchRecord;
}

Method.Source:
/// <summary>
/// AVA <c>includeRecordInInsertList</c> method
/// </summary>
/// <param name = "_searchRecord">common</param>
/// <returns>boolean</returns>
protected boolean includeRecordInInsertList(Common _searchRecord)
{
    boolean ret = next includeRecordInInsertList(_searchRecord);
    if (_searchRecord.TableId == tableNum(MCRInventTableIndex))
    {
        if (!existedSearchRecord)
        {
            existedSearchRecord = new Set(Types::Int64);
        }
        MCRInventTableIndex  indexTb = _searchRecord;

        if (existedSearchRecord.in(indexTb.RefRecId) )
        {
            ret = false;
        }

        existedSearchRecord.add(indexTb.RefRecId);

    }
    return ret;

}
